-- The helper's skills: the knowledge it coaches from, as data rather than code.
-- Each skill has a body (what it knows), triggers (the words that call it in),
-- sources, and an age range it applies to. "always_on" skills (the coaching
-- rules, red flags) go into every call; the rest are routed in per question,
-- so the prompt stays small and the cache stays warm. Admins edit them in the
-- app without a deploy.

create table if not exists public.assistant_skills (
  id            text primary key check (id ~ '^[a-z][a-z0-9_]*$'),
  title         text not null,
  "when"        text not null,                       -- one line for the index: when to use it
  triggers      text[] not null default '{}',        -- words or phrases (en, ar, ru) that call it in
  body          text not null,
  sources       text not null default '',
  always_on     boolean not null default false,
  age_from_days integer,                             -- null = any age
  age_to_days   integer,
  sort          integer not null default 100,
  is_active     boolean not null default true,
  version       integer not null default 1,
  updated_at    timestamptz not null default now(),
  updated_by    uuid references public.members (id) on delete set null
);
alter table public.assistant_skills enable row level security;
grant all on public.assistant_skills to service_role;

-- Everyone the helper serves may read the active skills (the helper runs as them).
create or replace function public.skill_list(p_all boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if public.current_member_id() is null or not public.has_permission('assistant', 'view') then return private.denied(); end if;
  if coalesce(p_all, false) and not public.has_permission('assistant', 'edit') then return private.denied(); end if;
  return jsonb_build_object('ok', true, 'items', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id, 'title', s.title, 'when', s."when", 'triggers', to_jsonb(s.triggers), 'body', s.body, 'sources', s.sources,
      'always_on', s.always_on, 'age_from_days', s.age_from_days, 'age_to_days', s.age_to_days, 'sort', s.sort,
      'is_active', s.is_active, 'version', s.version, 'updated_at', s.updated_at, 'updated_by', m.display_name) order by s.sort, s.id)
    from public.assistant_skills s
    left join public.members m on m.id = s.updated_by
    where s.is_active or coalesce(p_all, false)), '[]'::jsonb));
end $$;
grant execute on function public.skill_list(boolean) to authenticated, service_role;

-- Admins (assistant.edit) write. Every save bumps the version and is audited.
create or replace function public.skill_save(p_id text, p_title text, p_when text, p_triggers text[], p_body text, p_sources text default '', p_always_on boolean default false, p_age_from_days integer default null, p_age_to_days integer default null, p_sort integer default 100, p_is_active boolean default true) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_id text := lower(btrim(coalesce(p_id, '')));
begin
  if not private.authz('assistant', 'edit', 'assistant_skills', v_id) then return private.denied(); end if;
  if v_id !~ '^[a-z][a-z0-9_]{1,40}$' then return jsonb_build_object('ok', false, 'error', 'bad_id', 'message', 'Id: letters, digits and _ only.'); end if;
  if length(btrim(coalesce(p_title, ''))) < 2 or length(btrim(coalesce(p_body, ''))) < 20 then return jsonb_build_object('ok', false, 'error', 'bad_skill', 'message', 'A title and a body of at least 20 characters.'); end if;
  if length(p_body) > 6000 then return jsonb_build_object('ok', false, 'error', 'too_long', 'message', 'Keep a skill under 6000 characters; split it.'); end if;
  insert into public.assistant_skills (id, title, "when", triggers, body, sources, always_on, age_from_days, age_to_days, sort, is_active, updated_by)
  values (v_id, btrim(p_title), btrim(coalesce(p_when, '')), coalesce(p_triggers, '{}'), btrim(p_body), btrim(coalesce(p_sources, '')), coalesce(p_always_on, false), p_age_from_days, p_age_to_days, coalesce(p_sort, 100), coalesce(p_is_active, true), public.current_member_id())
  on conflict (id) do update set
    title = excluded.title, "when" = excluded."when", triggers = excluded.triggers, body = excluded.body, sources = excluded.sources,
    always_on = excluded.always_on, age_from_days = excluded.age_from_days, age_to_days = excluded.age_to_days, sort = excluded.sort,
    is_active = excluded.is_active, version = public.assistant_skills.version + 1, updated_at = now(), updated_by = excluded.updated_by;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;
grant execute on function public.skill_save(text, text, text, text[], text, text, boolean, integer, integer, integer, boolean) to authenticated, service_role;

-- The seed: what the helper coached from until now, split into skills, plus a few new ones.
insert into public.assistant_skills (id, title, "when", triggers, body, sources, always_on, age_from_days, age_to_days, sort) values
('coaching', 'How to coach', 'Always on: how the helper coaches.', '{}',
$body$When asked what to do about sleep, feeding rhythm, teething, growth spurts, regressions or building a habit, act as the family's baby coach. Look before you answer: call care_stats or sleep_rhythm and quote her real numbers. Say what is usual at her exact age (from her birth date and today's date), what is probably going on, then 2 to 4 gentle, concrete steps. One change at a time; give it 5 to 7 days. When a change takes several days, call propose_plan with a short day-by-day plan; the family starts it with one tap. If a plan is active (coach_plan), look at its check-ins and adapt; check plan_history first and never re-propose a plan that failed without changing it. Tools that are skills: age_outlook (which phase is now and next), day_schedule (a day rhythm from her wake time), red_flag_check (run it whenever illness, feeding refusal, fewer nappies or unusual sleepiness come up), recent_chats (pick up where an earlier chat left off), load_skill (read a skill from the index when the question needs it and it is not already shown). Memory: the things the family asked you to remember are listed above; use them naturally ("last time you said white noise helps"). When someone shares a durable fact or preference (what helped or did not, the family's approach such as no cry-it-out, a new tooth), call propose_memory with one short sentence; not one-off chit-chat or what the log already holds. Keep routines the same across everyone who cares for her. Talk to the person in front of you: a grandmother gets one clear thing to do, a parent gets the why as well. Not a doctor: no diagnoses, no medicine names or doses, nothing that breaks safe sleep. Red flags go to the paediatrician or 998, and the "When to call" page.$body$,
'House rules', true, null, null, 1),

('red_flags', 'Red flags', 'Always on: when to stop coaching and send them to the doctor.', '{}',
$body$RED FLAGS (doctor, or 998 if urgent): fever 38 °C or more under 3 months, breathing difficulty or pauses, blue or grey lips, very hard to wake or floppy, fewer than 6 wet nappies a day, refusing feeds for more than two feeds in a row, persistent vomiting or green vomit, blood in the stool, inconsolable crying for over an hour, a rash that does not fade under a glass, snoring with pauses, losing a skill she had, a bulging soft spot. When any of these comes up, say so first and plainly, point to "When to call", and do not continue coaching on top of it.$body$,
'NHS; AAP HealthyChildren', true, null, null, 2),

('sleep', 'Sleep by age', 'Naps, bedtime, night waking, awake windows, sleep norms.', '{sleep,nap,naps,bedtime,night,wake,waking,woke,awake,tired,overtired,drowsy,sleepy,settle,settling,"sleep training","white noise",cot,crib,swaddle,نوم,نام,تنام,قيلولة,سهر,спит,сон,спать,дневной,укладывать,просыпается}',
$body$SLEEP NORMS (totals in 24 h; wide individual variation): 0 to 3 months 14 to 17 h, awake windows 45 to 90 min, day and night confusion common until 6 to 8 weeks. 4 to 6 months 12 to 16 h with 3 to 4 naps, awake windows 1.5 to 2.5 h. 6 to 9 months 12 to 16 h, 2 to 3 naps, windows 2 to 3 h; the 3-to-2 nap change usually 7 to 9 months. 9 to 12 months 2 naps, windows 3 to 4 h. 12 to 18 months 11 to 14 h, 2-to-1 nap change 13 to 18 months. Short naps of 30 to 45 min (one sleep cycle) are normal under 5 to 6 months. Night feeds are normal and expected in the first 6 months, especially when breastfed.
HOW TO COACH SLEEP: use sleep_rhythm for her real awake windows and bedtime before advising. Overtired looks like wired, arching, hard to settle: bring the next sleep earlier, not later. Undertired looks like playing in the cot: stretch the window by 10 to 15 minutes. A consistent short wind-down (same 3 or 4 steps, same order) matters more than the clock. Drowsy-but-awake once a day from 3 to 4 months, never forced. Night: dim, boring, feed and change without play. Early waking (5 am) is usually bedtime too late or the last nap too short, rarely bedtime too early. One change at a time, 5 to 7 days.$body$,
'NHS; AAP HealthyChildren; Lullaby Trust', false, null, null, 10),

('safe_sleep', 'Safe sleep', 'Where and how she sleeps: cot, position, room, swaddling, co-sleeping.', '{"safe sleep",cot,crib,bassinet,"co-sleep",cosleep,"bed share",bedshare,"our bed",swaddle,swaddling,"sleep sack",blanket,pillow,bumper,"on her tummy","on her side","on his tummy",inclined,rocker,"car seat",temperature,"too hot",overheat,سرير,لحاف,وسادة,قماط,кроватка,пеленание,одеяло,подушка}',
$body$SAFE SLEEP (AAP 2022, NHS, Lullaby Trust): on her back for every sleep, firm flat separate surface in the parents' room for at least 6 months, no pillows, bumpers, loose blankets, wedges or soft toys, no inclined sleepers, swings or car seats for sleep (move her once home), room about 16 to 20 °C with light layers, no smoke, no hats indoors. A sleep sack instead of blankets. Stop swaddling at the first sign of rolling (often 3 to 4 months), arms out first. Bed-sharing is not advised; if it happens, never on a sofa or armchair, never after alcohol, medicines that cause drowsiness or smoking, and never with a baby under 3 months or born early. Dummies are fine for sleep once breastfeeding is settled. Say these plainly and kindly; never soften them to be agreeable.$body$,
'AAP 2022 safe sleep; NHS; Lullaby Trust', false, null, null, 11),

('regressions', 'Regressions and leaps', 'Sudden worse sleep or fussiness at 4, 8, 12 or 18 months; "leaps".', '{regression,regress,"suddenly","out of nowhere","used to sleep","was sleeping",leap,leaps,"wonder week",fussy,fussier,clingy,"separation anxiety",milestone,"4 month","four month","8 month","9 month","12 month","18 month",تراجع,فجأة,متعلقة,регресс,скачок,вдруг,капризный}',
$body$REGRESSIONS AND CHANGES: around 4 months (3 to 5) sleep cycles become adult-like, with more night waking and short naps for 2 to 6 weeks; keep the routine, practise drowsy-but-awake sometimes, avoid adding new sleep props you do not want long term. 8 to 10 months: crawling, standing, separation anxiety, the 3-to-2 nap change; practise the new skill by day, keep bedtime calm and the same. 12 and 18 months: walking, language, independence, the 2-to-1 nap change. "Leaps" and "wonder weeks" are popular but weakly supported; mention cautiously if at all, and check teething, illness, a growth spurt and a schedule drift first. Use age_outlook to say which phase she is in and what is coming. A regression is a phase, not a problem to fix: protect the routine and wait it out, 2 to 6 weeks.$body$,
'NHS; AAP HealthyChildren', false, 60, 600, 12),

('growth_spurts', 'Growth spurts', 'Feeding much more than usual, cluster feeding, hungrier, supply worries.', '{"growth spurt",spurt,"cluster feed","cluster feeding",hungrier,"more often","every hour","always hungry","not enough milk","low supply",supply,"feeding constantly","wants to feed",طفرة,جوعانة,"كل ساعة",حليب,скачок,кластерное,"каждый час",голодная,молока}',
$body$GROWTH SPURTS: common around 2 to 3 weeks, 6 weeks, 3, 6 and 9 months. Signs: frequent or cluster feeding, fussiness, sometimes more sleep. Usually 2 to 3 days. Feed on demand; it does not mean low supply: supply follows demand within a day or two. Reassure with the nappy count (6 or more wet a day) and weight gain. Evening cluster feeding is normal from the early weeks. Use care_stats to show the feeds per day rising, and age_outlook to say whether a spurt is due. If feeding stays very frequent beyond 4 or 5 days, or nappies drop, that is a feeding check with the doctor or a lactation consultant, not a spurt.$body$,
'NHS; La Leche League; AAP', false, null, 400, 13),

('feeding', 'Feeding', 'Breastfeeding, bottles, amounts, how often, expressed milk away from Mama.', '{feed,feeds,feeding,fed,breastfeed,breastfeeding,breast,boob,bottle,bottles,ml,formula,"how much","how often","too much","too little","not drinking",latch,"spit up","spitting up",reflux,burp,burping,wind,colic,hiccups,رضاعة,رضعة,زجاجة,ثدي,حليب,"كم مل",كمية,кормление,кормить,грудь,бутылочка,смесь,"сколько мл",срыгивает}',
$body$FEEDING (WHO, AAP, NHS): breast milk alone to about 6 months, responsive feeding (on cue, not by clock). 8 to 12 feeds a day early on, spacing out with age; by 3 to 4 months typically 6 to 8 feeds. Expressed milk away from Mama: roughly 25 to 30 ml per hour apart, 90 to 150 ml a bottle from 1 to 6 months; total breast milk stays about 750 to 800 ml a day from 1 to 6 months and does not keep rising like formula does. Paced bottle feeding (upright, slow-flow teat, pauses) helps a breastfed baby and stops over-feeding from a bottle. Spitting up small amounts after feeds is normal when she is gaining weight and content; forceful vomiting, poor weight gain or distress is the doctor's. Burp mid-feed and after. Wind and evening fussiness are common from 2 weeks to 3 months. Hunger cues before crying: rooting, hands to mouth, lip smacking; crying is a late cue. 6 or more wet nappies a day is reassuring. Use care_now for the last feed and the next due, care_stats for feeds per day and amounts; quote the numbers.$body$,
'WHO; AAP; NHS Start for Life', false, null, null, 14),

('milk', 'Pumped milk', 'Pumping, stash, thawing, how long milk keeps, how much to leave.', '{pump,pumping,pumped,express,expressed,stash,fridge,freezer,frozen,thaw,thawed,defrost,"milk left","enough milk","how much milk",bag,bags,storage,warm,warming,شفط,مضخة,ثلاجة,فريزر,مجمد,сцеживать,сцеженное,холодильник,морозилка,размораживать}',
$body$PUMPED MILK (NHS, CDC): freshly expressed milk keeps about 4 hours at room temperature, 4 days in the back of the fridge, 6 months in a freezer (up to 12 is acceptable). Thawed milk: 24 hours in the fridge, never refreeze; warm to body temperature in warm water, never a microwave; a bottle she has started can be finished within 2 hours, then discarded. Thaw the oldest first. Label with date and amount. Pumping after or between morning feeds gives the most; output is not a measure of supply. "How much milk is there" = pumped since yesterday evening minus bottles given from pumped milk today, and say it is an estimate from the log. The family's daytime target, if set, is in the household notes; use milk entries (lana.pump amount_ml) and bottle feeds that say which milk was used.$body$,
'NHS; CDC milk storage', false, null, null, 15),

('solids', 'Starting solids', 'Weaning, first foods, allergens, readiness, choking, water, cups.', '{solid,solids,wean,weaning,"first food","first foods",puree,purée,"baby led","finger food",allergen,allergy,peanut,egg,choke,choking,gag,gagging,water,cup,"sippy cup",spoon,طعام,أكل,فطام,تغذية,حساسية,прикорм,еда,пюре,аллерген,вода}',
$body$SOLIDS (NHS, AAP, WHO): around 6 months, never before 4 months (17 weeks). Ready when she sits with support with a steady head, has lost the tongue-thrust reflex and brings things to her mouth with interest; chewing fists or waking at night are not signs. Start with one meal a day of soft, iron-rich foods (vegetables, fruit, meat, lentils, iron-fortified cereal), textures moving on quickly; milk remains the main food until 12 months. Common allergens (egg, peanut, dairy, wheat, fish) early and often once solids start, one new one at a time, unless the doctor says otherwise. Gagging is normal and noisy; choking is silent: always seated upright, always watched, no whole grapes, nuts, hard raw vegetables or popcorn. Sips of water from an open cup with meals from 6 months; no juice; no honey before 1 year. Never add salt or sugar. Use care_stats to see how solids are affecting milk and nappies.$body$,
'NHS weaning; AAP; WHO', false, 100, 548, 16),

('teething', 'Teething', 'Drooling, chewing, gum pain, first teeth, teething and sleep.', '{teeth,tooth,teething,gum,gums,drool,drooling,chewing,"biting",dribble,طلوع,أسنان,سن,لثة,لعاب,зубы,зуб,зубки,десны,слюни}',
$body$TEETHING: first tooth usually 4 to 10 months, often a lower front one around 6 months; it can be months earlier or later. Signs: drooling, chewing everything, red or swollen gums, mild fussiness, slightly more night waking for a few days around the tooth coming through. Teething does not cause high fever, diarrhoea, a rash elsewhere or lasting illness; those need the doctor. Comfort: a clean cold (not frozen) teething ring or a cold flannel, a gentle gum rub with a clean finger, cuddles and distraction. Avoid amber necklaces (strangulation), benzocaine or lidocaine gels and homeopathic teething products. Pain relief medicine is the doctor's call; do not name medicines or doses. Brush the first teeth twice a day with a smear of fluoride toothpaste; first dental visit by the first birthday. Keep the sleep routine the same through it.$body$,
'NHS; AAP; FDA on benzocaine', false, 90, 900, 17),

('habits', 'Routines and habits', 'Bedtime routine, day rhythm, props, sleep training, keeping everyone consistent.', '{routine,routines,habit,habits,schedule,rhythm,"wind down","wind-down",consistent,consistency,prop,props,dummy,pacifier,rock,rocking,"feed to sleep","fed to sleep","sleep training","cry it out","ferber","pick up put down","shush pat",روتين,عادة,جدول,لهاية,هز,режим,привычка,соска,укачивать,"приучить"}',
$body$HABITS: a short, consistent bedtime routine at the same time from 6 to 8 weeks (wash, nappy, pyjamas, feed, song or book, bed), 20 to 30 minutes, same order every night and with every carer. Daylight and play by day, dim and boring at night. Feed, play, sleep in the day helps separate feeding from falling asleep (optional, not a rule). Drowsy-but-awake practice once a day from 3 to 4 months, never forced; feeding or rocking to sleep is not a mistake, only something to loosen gradually if the family wants to. Gentle settling (shush-pat, pick-up put-down, the chair method) before any graduated extinction; sleep training is generally not advised before about 6 months, and it is the family's choice; respect what they told you to remember. The one rule that matters most: everyone who cares for her does the same thing. When a change takes days, call propose_plan.$body$,
'NHS; AAP HealthyChildren', false, 30, null, 18),

('crying', 'Crying and soothing', 'Inconsolable crying, colic, witching hour, how to calm her.', '{cry,crying,cries,scream,screaming,inconsolable,colic,colicky,"witching hour",fuss,fussing,unsettled,calm,soothe,soothing,"calm her","calm him",frustrated,"losing it","can''t cope",exhausted,بكاء,تبكي,مغص,تهدئة,صراخ,плачет,плач,колики,успокоить,кричит}',
$body$CRYING: peaks around 6 to 8 weeks (up to 2 to 3 hours a day is within normal), settles by 3 to 4 months; the evening "witching hour" is common. Check in order: hungry (rooting, hands to mouth), wind, nappy, too hot or cold, tired (overtired is the usual one), overstimulated, wants holding. Soothing that works: swaddle (before rolling), side or stomach hold while awake in your arms, shushing or white noise, gentle swing or rocking, something to suck. A walk outside, a warm bath, skin to skin. Colic is crying over 3 hours a day, 3 days a week, in an otherwise well baby; it passes, and nothing sold for it is proven. The adult matters: if you feel you cannot cope, put her down safely on her back in the cot and step away for a few minutes; never shake a baby. A cry that sounds different (high-pitched, weak, moaning) or will not stop for over an hour with nothing helping is a doctor call, not a coaching question.$body$,
'NHS; AAP (Period of PURPLE Crying); ICON', false, null, 200, 19),

('illness', 'When she is unwell', 'Fever, cold, cough, vomiting, diarrhoea, rash, nappies dropping: what to watch and when to call.', '{fever,temperature,hot,"feels hot",cold,cough,coughing,snot,"runny nose",blocked,sneeze,vomit,vomiting,"threw up",diarrhoea,diarrhea,"runny poo",constipat,rash,spots,"not herself","not himself",unwell,sick,ill,poorly,lethargic,floppy,dehydrat,"dry nappies","fewer nappies",حرارة,سخونة,مريضة,تعبانة,سعال,كحة,استفراغ,إسهال,طفح,температура,жар,болеет,кашель,насморк,рвота,понос,сыпь}',
$body$WHEN SHE IS UNWELL: run red_flag_check first, then say plainly whether anything on the red-flag list applies. Fever: 38 °C or over is a fever; under 3 months any fever is a same-day doctor call; older, watch how she is rather than the number: feeding, wet nappies, alert when awake, consolable. Keep her lightly dressed, offer feeds often; never cold sponging. Colds: saline drops and a gentle nose clear before feeds, head of the mattress slightly raised only under the mattress, never pillows; most colds last 7 to 10 days; a cough alone can last 3 weeks. Vomiting and diarrhoea: smaller, more frequent feeds; the worry is dehydration (fewer than 6 wet nappies, dry mouth, no tears, sunken soft spot) and blood or green in vomit or stool. Constipation in a breastfed baby is rare; infrequent soft stools are normal; hard pellets, pain or blood are the doctor's. Rashes: the glass test; a rash that does not fade is 998. Never name a medicine or a dose; dosing is the doctor's or pharmacist's. Use care_stats to quantify (feeds, nappies, temperature entries) and cite them.$body$,
'NHS; AAP HealthyChildren', false, null, null, 20),

('development', 'Development and play', 'Milestones, tummy time, what she should be doing at her age, play ideas, screens.', '{develop,development,milestone,milestones,"tummy time",roll,rolling,sit,sitting,crawl,crawling,stand,standing,walk,walking,babble,babbling,talk,talking,words,smile,smiling,laugh,play,playing,toy,toys,book,books,screen,screens,tv,phone,"should she be","is she behind","is he behind",normal,نمو,تطور,تدحرج,جلوس,زحف,مشي,لعب,ألعاب,شاشة,развитие,переворачивается,сидит,ползает,ходит,играть,игрушки,экран,"должна уже"}',
$body$DEVELOPMENT: use age_outlook for the phase and milestones for her age; the Play page (/lana/activities) has age-matched ideas with sources. Typical order, with wide normal ranges: social smile 6 to 8 weeks; head steady and hands together 3 to 4 months; rolling 4 to 6 months; sitting with support 5 to 6 months, alone 6 to 8; babbling 6 to 9 months; crawling 7 to 10 (some never crawl); pulling to stand 9 to 12; first words around 12 months; walking 9 to 18 months. Tummy time from the first weeks, a few minutes several times a day while awake and watched, building to 15 to 30 minutes a day by 3 months; it also prevents a flat head. Talk, sing and read to her every day; respond to her sounds; name things. No screens under 18 months except video calls; background TV reduces talk. Red flags for development (doctor): not smiling by 3 months, not following with her eyes by 3 months, stiff or very floppy, not reaching by 6 months, no babble by 9 months, not pointing or waving by 12 months, losing a skill. Never diagnose; say what is typical and that the doctor checks at each visit.$body$,
'CDC milestones (2022); NHS; AAP HealthyChildren', false, null, null, 21),

('mama', 'Mama and the carers', 'The adults: recovery, feeding Mama, mood, sleep deprivation, when Mama is at work.', '{"postpartum","post partum","after birth",recovery,bleeding,stitches,mastitis,blocked,"blocked duct",engorged,engorgement,"sore nipple",nipples,thrush,mood,"feeling low",depressed,depression,anxious,anxiety,crying,"can''t sleep",exhausted,"back to work","at work","while mama","while dana",ماما,الأم,بعد الولادة,اكتئاب,قلق,متعبة,الشغل,"في العمل",мама,"после родов",депрессия,тревога,устала,"на работе"}',
$body$MAMA AND THE CARERS: a breastfeeding mother needs about 500 extra calories, water with every feed, and rest where it can be found; sleep in shifts when another adult is home. Engorgement, a blocked duct or sore nipples are common early and usually improve with frequent feeding, a good latch and warmth before and cold after feeds; a hot, red, painful area with fever or flu-like symptoms is mastitis and needs the doctor the same day. Low mood in the first two weeks is common ("baby blues"); low mood, anxiety, not sleeping even when the baby sleeps, or frightening thoughts lasting beyond two weeks is postnatal depression or anxiety and is treatable: encourage talking to the doctor or midwife, kindly and without alarm. If anyone speaks of harming themselves or the baby, give the emergency number and urge them to call now. When Mama is at work, the helper keeps the day running: bottles of expressed milk (see the feeding skill), the awake windows, and a handover note; use who_is_home and the routines. Do not take sides between carers; keep everyone doing the same routine.$body$,
'NHS; WHO; NICE antenatal and postnatal mental health', false, null, null, 22)
on conflict (id) do nothing;

-- Which skills a call used is recorded with the audit row's tools list ({name:"skills", input:[ids]}); no schema change needed.
